def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    On Windows, uses SetHandleInformation to modify the HANDLE_FLAG_INHERIT flag.
    This works for all handle types (files, pipes, events, etc.), not just file descriptors.
    """
    number = _as_number(handle)

    if os.name == "nt":
        from ._winapi import set_handle_information, HANDLE_FLAG_INHERIT
        try:
            flags = HANDLE_FLAG_INHERIT if enabled else 0
            set_handle_information(number, HANDLE_FLAG_INHERIT, flags)
        except OSError as exc:
            # Check if this is an unsupported operation
            # ERROR_INVALID_HANDLE (6) means the handle is invalid
            # Some handle types don't support inheritance modification
            winerror = getattr(exc, 'winerror', None) or exc.errno
            if winerror == 6:  # ERROR_INVALID_HANDLE
                raise WSpawnError("invalid handle", kind="badarg", handle=handle) from exc
            # For other errors, check if it's a type that doesn't support this
            # We'll treat most OS errors as "os" kind unless we know better
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc
    else:
        # Non-Windows fallback using os.set_inheritable (POSIX)
        try:
            os.set_inheritable(number, bool(enabled))
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc
        except (TypeError, ValueError) as exc:
            raise WSpawnError(str(exc), kind="badarg", handle=handle) from exc


