    """Return ``True`` when ``handle`` is currently transferable.

    On Windows, uses GetHandleInformation to check the HANDLE_FLAG_INHERIT flag.
    """
    number = _as_number(handle)

    if os.name == "nt":
        from ._winapi import get_handle_information, HANDLE_FLAG_INHERIT
        try:
            flags = get_handle_information(number)
            return bool(flags & HANDLE_FLAG_INHERIT)
        except OSError as exc:
            winerror = getattr(exc, 'winerror', None) or exc.errno
            if winerror == 6:  # ERROR_INVALID_HANDLE
                raise WSpawnError("invalid handle", kind="badarg", handle=handle) from exc
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc
    else:
        try:
            return bool(os.get_inheritable(number))
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os", handle=handle) from exc


# Track handles that have been marked inheritable by this module
_tracked_inheritable = set()


def _track_handle(handle):
    """Track a handle as potentially inheritable."""
    _tracked_inheritable.add(int(handle))


def _untrack_handle(handle):
    """Stop tracking a handle."""
    _tracked_inheritable.discard(int(handle))


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Returns handles that have been marked inheritable via set_inheritable().
    Note: This only tracks handles modified through this module; handles
    marked inheritable through other means may not be reported.
    """
    # Verify which tracked handles are still actually inheritable
    result = []
    for h in list(_tracked_inheritable):
        try:
            if is_inheritable(h):
                result.append(h)
            else:
                _untrack_handle(h)
        except WSpawnError:
            # Handle is no longer valid
            _untrack_handle(h)
    return tuple(result)

