    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")

    if number < 0:
        raise WSpawnError("not a usable object handle: %r" % (handle,), kind="badarg", handle=handle)

    if os.name == "nt":
        from ._winapi import file_type, FILE_TYPE_DISK, FILE_TYPE_PIPE, FILE_TYPE_CHAR

        try:
            ft = file_type(number)
        except OSError as exc:
            # Invalid handle or other error
            winerror = getattr(exc, 'winerror', None) or exc.errno
            if winerror == 6:  # ERROR_INVALID_HANDLE
                raise WSpawnError("invalid handle", kind="badarg", handle=handle) from exc
