    return None


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    On Windows, uses PROC_THREAD_ATTRIBUTE_HANDLE_LIST to ensure only the
    specified handles are inherited by the child process. The handles in
    ``inherit`` plus any explicitly specified standard streams will be
    available in the child with the same numeric values.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    if os.name == "nt":
        return _spawn_windows(command, handles, stdin, stdout, stderr)
    else:
        return _spawn_posix(command, handles, stdin, stdout, stderr)


def _spawn_windows(command, handles, stdin, stdout, stderr):
    """Windows-specific spawn using precise handle inheritance."""
    from ._winapi import create_process_with_handle_list, get_std_handle
    from ._winapi import STD_INPUT_HANDLE, STD_OUTPUT_HANDLE, STD_ERROR_HANDLE

    # Get handle values for standard streams
    stdin_val = _get_handle_value(stdin)
    stdout_val = _get_handle_value(stdout)
    stderr_val = _get_handle_value(stderr)

    # Handle subprocess.DEVNULL by opening NUL device
    if stdin_val == _SUBPROCESS_DEVNULL:
        stdin_handle = _open_nul_read()
    elif stdin_val is None:
        stdin_handle = None  # Will use parent's stdin
    else:
        stdin_handle = stdin_val

    if stdout_val == _SUBPROCESS_DEVNULL:
        stdout_handle = _open_nul_write()
    elif stdout_val is None:
        stdout_handle = None  # Will use parent's stdout
    else:
        stdout_handle = stdout_val

    if stderr_val == _SUBPROCESS_DEVNULL:
        stderr_handle = _open_nul_write()
    elif stderr_val is None:
        stderr_handle = None  # Will use parent's stderr
    else:
        stderr_handle = stderr_val

    # Build command line string
    cmd_line = subprocess.list2cmdline(command)

    try:
        proc_handle, thread_handle, pid = create_process_with_handle_list(
            cmd_line,
            handles,
            stdin=stdin_handle,
            stdout=stdout_handle,
            stderr=stderr_handle
        )
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os") from exc
    finally:
        # Close NUL handles we opened (they've been inherited by child)
        # Actually, we should NOT close them here because the child needs them
        # But since they're inherited, closing in parent is fine
        if stdin_val == _SUBPROCESS_DEVNULL and stdin_handle is not None:
            try:
                from ._winapi import close_handle
                close_handle(stdin_handle)
            except Exception:
                pass
        if stdout_val == _SUBPROCESS_DEVNULL and stdout_handle is not None:
            try:
                from ._winapi import close_handle
                close_handle(stdout_handle)
            except Exception:
                pass
        if stderr_val == _SUBPROCESS_DEVNULL and stderr_handle is not None:
            try:
                from ._winapi import close_handle
                close_handle(stderr_handle)
            except Exception:
                pass

    # Create a wrapper that mimics Popen interface
    class _WindowsProcessWrapper:
        def __init__(self, proc_handle, thread_handle, pid):
            self._proc_handle = proc_handle
            self._thread_handle = thread_handle
            self.pid = pid
            self.returncode = None

        def wait(self, timeout=None):
            from ._winapi import wait_for_single_object, get_exit_code_process
            from ._winapi import WAIT_OBJECT_0, WAIT_TIMEOUT, INFINITE

            if timeout is None:
                wait_ms = INFINITE
            else:
                wait_ms = int(timeout * 1000)

            result = wait_for_single_object(self._proc_handle, wait_ms)

            if result == WAIT_OBJECT_0:
                self.returncode = get_exit_code_process(self._proc_handle)
            elif result == WAIT_TIMEOUT:
                raise subprocess.TimeoutExpired(cmd=command, timeout=timeout)
            else:
                raise OSError("WaitForSingleObject failed with result %d" % result)

            return self.returncode

        def poll(self):
            from ._winapi import wait_for_single_object, get_exit_code_process
            from ._winapi import WAIT_OBJECT_0

            result = wait_for_single_object(self._proc_handle, 0)

            if result == WAIT_OBJECT_0:
                self.returncode = get_exit_code_process(self._proc_handle)

            return self.returncode

        def terminate(self):
            from ._winapi import terminate_process
            terminate_process(self._proc_handle, 1)

        def __del__(self):
            try:
                from ._winapi import close_handle
                if hasattr(self, '_proc_handle') and self._proc_handle:
                    close_handle(self._proc_handle)
                    self._proc_handle = None
                if hasattr(self, '_thread_handle') and self._thread_handle:
                    close_handle(self._thread_handle)
                    self._thread_handle = None
            except Exception:
                pass

    wrapper = _WindowsProcessWrapper(proc_handle, thread_handle, pid)
    return SpawnedProcess(wrapper, handles)


def _open_nul_read():
    """Open NUL device for reading. Returns a Windows handle."""
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

    GENERIC_READ = 0x80000000
    FILE_SHARE_READ = 0x00000001
    OPEN_EXISTING = 3

    handle = kernel32.CreateFileW(
        "NUL",
        GENERIC_READ,
        FILE_SHARE_READ,
        None,
        OPEN_EXISTING,
        0,
        None
    )

    if handle == -1 or handle == 0xFFFFFFFF:
        err = ctypes.get_last_error()
        raise OSError(err, "Failed to open NUL for reading")

    return int(handle)


def _open_nul_write():
    """Open NUL device for writing. Returns a Windows handle."""
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

    GENERIC_WRITE = 0x40000000
    FILE_SHARE_WRITE = 0x00000002
    OPEN_EXISTING = 3

    handle = kernel32.CreateFileW(
        "NUL",
        GENERIC_WRITE,
        FILE_SHARE_WRITE,
        None,
        OPEN_EXISTING,
        0,
        None
    )

    if handle == -1 or handle == 0xFFFFFFFF:
        err = ctypes.get_last_error()
        raise OSError(err, "Failed to open NUL for writing")

    return int(handle)


def _spawn_posix(command, handles, stdin, stdout, stderr):
    """POSIX fallback spawn (not used on Windows, kept for completeness)."""
    kwargs = {
        "close_fds": True,
        "stdin": stdin,
        "stdout": stdout,
        "stderr": stderr,
    }

    try:
        popen = subprocess.Popen(command, **kwargs)
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os") from exc
    return SpawnedProcess(popen, handles)
